    let azureResponse: Response;
    try {
      azureResponse = await fetch(
        Deno.env.get("AZURE_OPENAI_ENDPOINT")!,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "api-key": Deno.env.get("AZURE_OPENAI_API_KEY")!,
          },
          body: JSON.stringify({
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: userPrompt },
            ],
            max_completion_tokens: 2000,
            response_format: { type: "json_object" },
            reasoning_effort: "low",
            verbosity: "low"
          }),
          signal: controller.signal
        }
      );
      clearTimeout(timeoutId);
    } catch (error: unknown) {
      clearTimeout(timeoutId);
      if (error.name === 'AbortError') {
        console.error("Azure request timeout (90s)");
        throw new Error("Azure request timeout (90s)");
      }
      throw error;
    }

    if (!azureResponse.ok) {
      const errorText = await azureResponse.text();
      console.error("Azure OpenAI error:", errorText);
      throw new Error(`Azure OpenAI API error: $${azureResponse.status}`);
    }

    const azureData = await azureResponse.json();
    const aiResult = JSON.parse(azureData.choices[0].message.content);
    const suggestions = aiResult.suggestions || [];

    // LOG DEBUG : vérifier les suggestions générées
    console.log(`📊 AI generated $${suggestions.length} suggestions for $${entityType} $${entity?.nom}`);
    suggestions.forEach((s: any, idx: number) => {
      console.log(`  $${idx + 1}. $${s.action_type} (confidence: $${s.confidence_score})`);
      if (s.action_type === 'update_task') {
        console.log(`     → task_id: $${s.action_data?.task_id}`);
      }
    });

    // SECURITY: Allowed action types (DB constraint)
    const ALLOWED_ACTIONS = ['update_task', 'create_task', 'change_status', 'update_summary'];

    // Function to validate action_data structure
    function validateActionData(action_type: string, action_data: any): { valid: boolean; reason?: string } {
      switch (action_type) {
        case 'update_task':
          if (!action_data?.task_id) {
            return { valid: false, reason: 'task_id manquant' };
          }
          if (!action_data?.new_status) {
            return { valid: false, reason: 'new_status manquant' };
          }
          return { valid: true };

        case 'create_task':
          if (!action_data?.title) {
            return { valid: false, reason: 'title manquant' };
          }

          // Phase 2 : Vérifier que ce n'est pas une action "outgoing" mal placée
          const title = action_data.title.toLowerCase();
          const outgoingKeywords = ['envoyer', 'transmettre', 'fournir', 'livrer', 'donner'];
          const isLikelyOutgoing = outgoingKeywords.some((kw: string) => title.includes(kw));

          if (isLikelyOutgoing && !title.includes('suivre')) {
            console.warn(`⚠️ Phase 2: Possible outgoing action in create_task: "$${action_data.title}"`);
            console.warn(`  → Should this be a follow-up task instead?`);
            // Ne pas rejeter, mais log pour monitoring
          }

          return { valid: true };

        case 'change_status':
          if (!action_data?.new_status) {
            return { valid: false, reason: 'new_status manquant' };
          }
          return { valid: true };

        case 'update_summary':
          if (!action_data?.summary_text) {
            return { valid: false, reason: 'summary_text manquant' };
          }
          return { valid: true };

        default:
          return { valid: false, reason: 'action_type inconnu' };
      }
    }

    // Phase 1: Déduplication AVANT filtrage
    console.log(`📊 Suggestions brutes reçues de l'IA: $${suggestions.length}`);
    const deduplicatedSuggestions = deduplicateSuggestions(suggestions);

    // Filter high confidence suggestions, validate action types AND action_data
    const validSuggestions = [];
    const invalidSuggestions = [];

    for (const s of deduplicatedSuggestions) {
      // Check confidence (Phase 1: seuil augmenté à 0.85)
      if (s.confidence_score < MIN_CONFIDENCE) {
        invalidSuggestions.push({ ...s, reject_reason: `confidence_score trop faible (< $${MIN_CONFIDENCE})` });
        continue;
      }

      // Check allowed action type
      if (!ALLOWED_ACTIONS.includes(s.action_type)) {
        invalidSuggestions.push({ ...s, reject_reason: 'action_type non autorisé' });
        continue;
      }

      // Validate action_data structure
      const validation = validateActionData(s.action_type, s.action_data);
      if (!validation.valid) {
        invalidSuggestions.push({ ...s, reject_reason: `action_data invalide: $${validation.reason}` });
        continue;
      }

      validSuggestions.push(s);
    }

    // Phase 1: Limiter à MAX_SUGGESTIONS_PER_EMAIL (3 suggestions max)
    const finalSuggestions = validSuggestions
      .sort((a, b) => (b.confidence_score || 0) - (a.confidence_score || 0)) // Trier par confiance décroissante
      .slice(0, MAX_SUGGESTIONS_PER_EMAIL);

    if (validSuggestions.length > MAX_SUGGESTIONS_PER_EMAIL) {
      const rejected = validSuggestions.slice(MAX_SUGGESTIONS_PER_EMAIL);
      rejected.forEach((s: any) => {
        invalidSuggestions.push({ 
          ...s, 
          reject_reason: `Limite de $${MAX_SUGGESTIONS_PER_EMAIL} suggestions atteinte (score: $${s.confidence_score})` 
        });
      });
      console.log(`⚠️ Limité à $${MAX_SUGGESTIONS_PER_EMAIL} suggestions ($${rejected.length} suggestions valides supplémentaires écartées)`);
    }

    // Log rejected suggestions for debugging
    if (invalidSuggestions.length > 0) {
      console.warn(`⚠️ Rejected $${invalidSuggestions.length} invalid suggestions:`);
      invalidSuggestions.forEach((s: any) => {
        console.warn(`  - $${s.action_type}: $${s.reject_reason}`);
        if (s.action_type === 'update_task') {
          console.warn(`    action_data: $${JSON.stringify(s.action_data)}`);
        }
      });
    }

    console.log(`✅ $${finalSuggestions.length} suggestions finales retenues (après déduplication, filtrage confiance >= $${MIN_CONFIDENCE}, et limite de $${MAX_SUGGESTIONS_PER_EMAIL})`);

    const insertedSuggestions = [];
    for (const suggestion of finalSuggestions) {
      try {
        // PHASE 2 : Vérification anti-doublon au niveau ÉTABLISSEMENT (pas juste thread)
        let deduplicationQuery = supabase
          .from("ai_suggested_actions")
          .select("id, action_type, action_data, confidence_score")
          .eq("action_type", suggestion.action_type)
          .eq("status", "pending");

        // Élargir la vérification au niveau établissement ou partenaire
        if (etablissement_id) {
          deduplicationQuery = deduplicationQuery.eq("etablissement_id", etablissement_id);
        } else if (partenaire_id) {
          deduplicationQuery = deduplicationQuery.eq("partenaire_id", partenaire_id);
        } else {
          // Fallback : vérifier au moins au niveau thread
          deduplicationQuery = deduplicationQuery.eq("email_thread_id", thread_id);
        }

        const { data: existingSuggestions } = await deduplicationQuery;

        // Utiliser la fonction de similarité sémantique améliorée
        const isDuplicate = existingSuggestions?.some((existing: any) => 
          areSuggestionsSimilar(suggestion, existing)
        );

        if (isDuplicate) {
          console.log(`⏭️ Skipping duplicate suggestion (établissement-wide): $${suggestion.action_type} - $${suggestion.action_data?.title || 'N/A'}`);
          continue;
        }

        const { data: inserted, error: insertError } = await supabase
          .from("ai_suggested_actions")
          .insert({
            email_thread_id: thread_id,
            etablissement_id: etablissement_id || null,
            partenaire_id: partenaire_id || null,
            action_type: suggestion.action_type,
            action_data: suggestion.action_data,
            confidence_score: suggestion.confidence_score,
            reason: suggestion.reason,
            status: 'pending'
          })
          .select()
          .single();

        if (insertError) {
          console.error(`Failed to insert suggestion $${suggestion.action_type}:`, insertError);
        } else if (inserted) {
          insertedSuggestions.push(inserted);
        }
      } catch (error) {
        console.error(`Error inserting suggestion:`, error);
      }
    }

    // Log the AI processing
    await supabase.from("ai_processing_log").insert({
      email_thread_id: thread_id,
      processing_type: "suggestion_generation",
      model_used: "gpt-5.4",
      prompt_tokens: azureData.usage?.prompt_tokens,
      completion_tokens: azureData.usage?.completion_tokens,
      total_tokens: azureData.usage?.total_tokens,
      result: { 
        suggestions_raw: suggestions.length,
        suggestions_after_dedup: deduplicatedSuggestions.length,
        suggestions_final: finalSuggestions.length,
        suggestions: finalSuggestions 
      },
      success: true,
    });

    // Create in-app notifications for relevant users
    if (insertedSuggestions.length > 0 && entity) {
      const usersToNotify = new Set<string>();
      let entityName = '';

      if (entityType === 'etablissement') {
        entityName = entity.nom;

        // Get user_ids for notifications based on establishment roles
        if (entity.commercial_id) {
          const { data: commercial } = await supabase
            .from('profiles')
            .select('user_id')
            .eq('id', entity.commercial_id)
            .single();
          if (commercial?.user_id) usersToNotify.add(commercial.user_id);
        }

        if (entity.chef_projet_id) {
          const { data: chef_projet } = await supabase
            .from('profiles')
            .select('user_id')
            .eq('id', entity.chef_projet_id)
            .single();
          if (chef_projet?.user_id) usersToNotify.add(chef_projet.user_id);
        }

        if (entity.csm_id) {
          const { data: csm } = await supabase
            .from('profiles')
            .select('user_id')
            .eq('id', entity.csm_id)
            .single();
          if (csm?.user_id) usersToNotify.add(csm.user_id);
        }
      } else if (entityType === 'partenaire') {
        entityName = entity.nom;

        if (entity.responsable_sclepios_id) {
          const { data: responsable } = await supabase
            .from('profiles')
            .select('user_id')
            .eq('id', entity.responsable_sclepios_id)
            .single();
          if (responsable?.user_id) usersToNotify.add(responsable.user_id);
        }
      }

      // Send notifications to each user
      for (const userId of usersToNotify) {
        await supabase.functions.invoke('create-in-app-notification', {
          body: {
            user_id: userId,
            title: `$${insertedSuggestions.length} suggestion$${insertedSuggestions.length > 1 ? 's' : ''} IA`,
            message: `L'IA a généré $${insertedSuggestions.length} suggestion$${insertedSuggestions.length > 1 ? 's' : ''} pour $${entityName}`,
            type: 'ai_suggestion',
            related_id: etablissement_id || partenaire_id,
            related_type: entityType,
          },
        });
      }
    }

    return new Response(JSON.stringify({
      success: true,
      suggestions_count: insertedSuggestions.length,
      suggestions: insertedSuggestions
    }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" }
    });

  } catch (error) {
    console.error("Error in generate-ai-suggestions:", error);
    return buildErrorResponse('generate-ai-suggestions', error, corsHeaders, 500);
  }
});

/**
 * jarvis-vision - Analyse d'images avec GPT-5 Vision
 * 
 * Supporte OCR, analyse documentaire, extraction de données
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { logAICall, createTimer, extractUsage } from "../_shared/ai-logging.ts";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version',
};

const AZURE_OPENAI_ENDPOINT = Deno.env.get('AZURE_OPENAI_ENDPOINT');
const AZURE_OPENAI_API_KEY = Deno.env.get('AZURE_OPENAI_API_KEY');

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const timer = createTimer();

  try {
    // Authentification OBLIGATOIRE - prévient l'abus de l'API Vision
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(JSON.stringify({ success: false, error: 'Unauthorized' }), {
        status: 401,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_ANON_KEY')!,
      { global: { headers: { Authorization: authHeader } } }
    );

    const token = authHeader.replace('Bearer ', '');
    const { data: claimsData, error: authError } = await supabase.auth.getClaims(token);
    const userId = claimsData?.claims?.sub as string | undefined;

    if (authError || !userId) {
      return new Response(JSON.stringify({ success: false, error: 'Unauthorized' }), {
        status: 401,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    const { image_base64, image_url, prompt, task } = await req.json();

    if (!image_base64 && !image_url) {
      return new Response(JSON.stringify({ 
        success: false, 
        error: 'Image required (base64 or URL)' 
      }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    if (!AZURE_OPENAI_ENDPOINT || !AZURE_OPENAI_API_KEY) {
      return new Response(JSON.stringify({ 
        success: false, 
        error: 'Azure OpenAI not configured' 
      }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Build vision message
    const imageContent = image_base64 
      ? { type: 'image_url', image_url: { url: `data:image/jpeg;base64,$${image_base64}` } }
      : { type: 'image_url', image_url: { url: image_url } };

    // Task-specific system prompts
    const systemPrompts: Record<string, string> = {
      'ocr': `Tu es un expert en OCR pour Sclépios IA. 
Extrais tout le texte visible de cette image, préserve la structure et la mise en forme.
Utilise des retours à la ligne et de l'indentation pour représenter la mise en page originale.
Si le document contient des tableaux, représente-les clairement.`,

      'analyze': `Tu es un expert en analyse documentaire pour Sclépios IA.
Analyse cette image et décris son contenu de manière détaillée et structurée.
Identifie le type de document, les éléments clés, et toute information pertinente.`,

      'extract_data': `Tu es un expert en extraction de données pour Sclépios IA.
Identifie et structure toutes les données clés de ce document.
Retourne les données au format JSON avec les champs suivants si présents:
- noms, prénoms, identités
- dates (formats ISO)
- montants (en nombres)
- adresses
- numéros de téléphone
- emails
- références et numéros de document
- toute autre donnée structurée pertinente`,

      'summarize': `Tu es un assistant Sclépios IA.
Résume le contenu de cette image en quelques phrases claires et concises.
Focus sur les informations les plus importantes et actionnables.`,
    };

    const systemPrompt = systemPrompts[task] || systemPrompts['analyze'];

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 90000);

    let response: Response;
    try {
      response = await fetch(AZURE_OPENAI_ENDPOINT, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'api-key': AZURE_OPENAI_API_KEY,
        },
        body: JSON.stringify({
          messages: [
            { role: 'system', content: systemPrompt },
            {
              role: 'user',
              content: [
                imageContent,
                { type: 'text', text: prompt || 'Analyse cette image.' }
              ]
            }
          ],
          max_completion_tokens: 4000,
          reasoning_effort: 'medium',
          verbosity: 'medium',
        }),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      // Retry sur rate limit
      if (response.status === 429) {
        console.warn('[jarvis-vision] Rate limited, retrying in 1s...');
        await new Promise(r => setTimeout(r, 1000));
        response = await fetch(AZURE_OPENAI_ENDPOINT, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'api-key': AZURE_OPENAI_API_KEY,
          },
          body: JSON.stringify({
            messages: [
              { role: 'system', content: systemPrompt },
              {
                role: 'user',
                content: [
                  imageContent,
                  { type: 'text', text: prompt || 'Analyse cette image.' }
                ]
              }
            ],
            max_completion_tokens: 4000,
            reasoning_effort: 'medium',
            verbosity: 'medium',
          }),
        });
      }
    } catch (error: unknown) {
      clearTimeout(timeoutId);
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error('Azure request timeout (90s)');
      }
      throw error;
    }

    if (!response.ok) {
      const errorText = await response.text();
      console.error(`[jarvis-vision] Azure error: $${response.status}`, errorText);
      throw new Error(`Azure Vision error: $${response.status}`);
    }

    const data = await response.json();
    const content = data.choices?.[0]?.message?.content;
    const usage = extractUsage(data);
    const duration = timer.stop();

    // Log AI call
    await logAICall({
      processing_type: `jarvis-vision-$${task}`,
      model_used: 'gpt-5-vision',
      ...usage,
      processing_duration_ms: duration,
      success: true,
      result: { task, content_length: content?.length || 0 },
      processed_by: userId,
    });

    console.log(`[jarvis-vision] Analysis completed ($${task}) in $${duration}ms`);

    return new Response(JSON.stringify({
      success: true,
      content,
      task,
      usage,
    }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });

  } catch (error) {
    console.error('[jarvis-vision] Error:', error);

    await logAICall({
      processing_type: 'jarvis-vision',
      model_used: 'gpt-5-vision',
      processing_duration_ms: timer.stop(),
      success: false,
      error_message: error instanceof Error ? error.message : 'Unknown error',
    });

    return buildErrorResponse('jarvis-vision', error, corsHeaders, 500);
  }
});

/**
 * jarvis-voice-intent - Détection d'intentions vocales pour le handoff multi-agent
 * 
 * JARVIS 6.0: Analyse le texte transcrit pour détecter les intentions de handoff,
 * les commandes de conférence et les actions spécifiques
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { validateServiceOrUser } from "../_shared/auth-helpers.ts";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Agent keywords for intent detection
const AGENT_KEYWORDS: Record<string, string[]> = {
  prime: ['jarvis', 'coordinateur', 'chef', 'équipe complète', 'tout le monde', 'briefing'],
  sophia: ['sophia', 'client', 'prospect', 'commercial', 'vente', 'établissement', 'crm', 'relance', 'contrat'],
  marcus: ['marcus', 'rh', 'équipe', 'absence', 'congé', 'recrutement', 'paie', 'collaborateur', 'salaire'],
  olivia: ['olivia', 'trésorerie', 'facture', 'paiement', 'finance', 'budget', 'banque', 'dépense', 'qonto'],
  noah: ['noah', 'r&d', 'développement', 'sprint', 'epic', 'story', 'backlog', 'feature', 'bug'],
  emma: ['emma', 'support', 'ticket', 'problème', 'aide', 'incident', 'assistance'],
  alex: ['alex', 'analyse', 'stats', 'rapport', 'tendance', 'kpi', 'prédiction', 'insight', 'dashboard'],
};

// Conference trigger phrases
const CONFERENCE_TRIGGERS = [
  'briefing',
  'point complet',
  'tour de table',
  'réunion équipe',
  'tout le monde',
  'équipe complète',
  'avis de tous',
  'qu\'en pensez-vous tous',
];

// Direct handoff phrases
const HANDOFF_TRIGGERS = [
  'appelle',
  'passe à',
  'demande à',
  'qu\'en pense',
  'avis de',
  'parle à',
  'passe-moi',
  'je veux parler à',
];

interface VoiceIntent {
  type: 'handoff' | 'conference' | 'action' | 'question' | 'unknown';
  targetAgent?: string;
  conferenceAgents?: string[];
  confidence: number;
  originalText: string;
  suggestedResponse?: string;
}

/**
 * Normalise le texte pour la comparaison
 */
function normalizeText(text: string): string {
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // Remove accents
    .replace(/['']/g, "'")
    .trim();
}

/**
 * Détecte si le texte déclenche une conférence
 */
function detectConference(normalizedText: string): boolean {
  return CONFERENCE_TRIGGERS.some(trigger => normalizedText.includes(trigger));
}

/**
 * Détecte si le texte déclenche un handoff direct
 */
function detectDirectHandoff(normalizedText: string): { agent: string; confidence: number } | null {
  // Check for explicit agent name mention
  for (const [agentId, keywords] of Object.entries(AGENT_KEYWORDS)) {
    for (const keyword of keywords) {
      if (normalizedText.includes(keyword)) {
        // Check if it's a direct handoff phrase
        const isDirectHandoff = HANDOFF_TRIGGERS.some(trigger => normalizedText.includes(trigger));
        if (isDirectHandoff || keyword === agentId) {
          return { agent: agentId, confidence: 0.9 };
        }
      }
    }
  }
  return null;
}

/**
 * Détecte l'agent le plus pertinent basé sur le contexte
 */
function detectContextualAgent(normalizedText: string): { agent: string; confidence: number } | null {
  const scores: Record<string, number> = {};

  for (const [agentId, keywords] of Object.entries(AGENT_KEYWORDS)) {
    scores[agentId] = 0;
    for (const keyword of keywords) {
      if (normalizedText.includes(keyword)) {
        scores[agentId] += keyword.length; // Weight by keyword length
      }
    }
  }

  // Find best match
  let bestAgent: string | null = null;
  let bestScore = 0;

  for (const [agentId, score] of Object.entries(scores)) {
    if (score > bestScore) {
      bestScore = score;
      bestAgent = agentId;
    }
  }

  if (bestAgent && bestScore > 3) {
    return { agent: bestAgent, confidence: Math.min(0.9, 0.3 + bestScore * 0.1) };
  }

  return null;
}

/**
 * Génère une réponse suggérée pour le handoff
 */
function getHandoffSuggestion(agentId: string): string {
  const suggestions: Record<string, string[]> = {
    prime: ["Je reprends la coordination.", "Jarvis à l'écoute."],
    sophia: ["Sophia prend le relais pour la partie commerciale.", "Je m'occupe de ce client."],
    marcus: ["Marcus à votre service pour les RH.", "Je prends en charge cette question d'équipe."],
    olivia: ["Olivia prend la main pour la trésorerie.", "Je m'occupe des finances."],
    noah: ["Noah au clavier pour la R&D.", "Je prends en charge cette question technique."],
    emma: ["Emma ici pour le support.", "Je m'occupe de ce problème."],
    alex: ["Alex prend le relais pour l'analyse.", "Je vais examiner ces données."],
  };

  const agentSuggestions = suggestions[agentId] || suggestions.prime;
  return agentSuggestions[Math.floor(Math.random() * agentSuggestions.length)];
}

serve(async (req) => {
  // CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const auth = await validateServiceOrUser(req);
    if (!auth.authorized) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }
    const body = await req.json();
    const { text, currentAgent } = body;
    const userId = auth.isServiceCall ? body.userId : auth.userId;


    if (!text) {
      return new Response(
        JSON.stringify({ error: 'Text is required' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    console.log('[jarvis-voice-intent] Analyzing text:', text);
    console.log('[jarvis-voice-intent] Current agent:', currentAgent);

    const normalizedText = normalizeText(text);
    let intent: VoiceIntent;

    // 1. Check for conference trigger
    if (detectConference(normalizedText)) {
      console.log('[jarvis-voice-intent] Conference detected');
      intent = {
        type: 'conference',
        conferenceAgents: ['sophia', 'marcus', 'olivia', 'noah', 'emma', 'alex'],
        confidence: 0.95,
        originalText: text,
        suggestedResponse: "Je lance le briefing d'équipe. Chaque membre va intervenir.",
      };
    }
    // 2. Check for direct handoff
    else {
      const directHandoff = detectDirectHandoff(normalizedText);

      if (directHandoff && directHandoff.agent !== currentAgent) {
        console.log('[jarvis-voice-intent] Direct handoff to:', directHandoff.agent);
        intent = {
          type: 'handoff',
          targetAgent: directHandoff.agent,
          confidence: directHandoff.confidence,
          originalText: text,
          suggestedResponse: getHandoffSuggestion(directHandoff.agent),
        };
      }
      // 3. Check for contextual agent switch
      else {
        const contextualAgent = detectContextualAgent(normalizedText);

        if (contextualAgent && contextualAgent.agent !== currentAgent && contextualAgent.confidence > 0.5) {
          console.log('[jarvis-voice-intent] Contextual handoff to:', contextualAgent.agent);
          intent = {
            type: 'handoff',
            targetAgent: contextualAgent.agent,
            confidence: contextualAgent.confidence,
            originalText: text,
            suggestedResponse: getHandoffSuggestion(contextualAgent.agent),
          };
        }
        // 4. Regular question/action
        else {
          intent = {
            type: 'question',
            targetAgent: currentAgent || 'prime',
            confidence: 0.7,
            originalText: text,
          };
        }
      }
    }

    console.log('[jarvis-voice-intent] Intent result:', intent);

    // Log to database for learning
    if (userId) {
      try {
        const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
        const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
        const supabase = createClient(supabaseUrl, supabaseServiceKey);

        await supabase.from('jarvis_usage_patterns').insert({
          user_id: userId,
          pattern_type: 'voice_intent',
          pattern_data: {
            text: text.substring(0, 500),
            intent_type: intent.type,
            target_agent: intent.targetAgent,
            confidence: intent.confidence,
            current_agent: currentAgent,
          },
          confidence: intent.confidence,
        });
      } catch (logError: unknown) {
        console.warn('[jarvis-voice-intent] Failed to log pattern:', logError);
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        intent,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error: unknown) {
    console.error('[jarvis-voice-intent] Error:', error);
    return buildErrorResponse('jarvis-voice-intent', error, corsHeaders, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { sanitizeForAI, wrapUserContent, logSecurityEvent } from "../_shared/security-utils.ts";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";
import { checkRateLimit } from "../_shared/rate-limit.ts";
import { requireInternalSecret } from "../_shared/internal-secret.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-internal-secret, x-session-token',
};

const AZURE_OPENAI_ENDPOINT = Deno.env.get('AZURE_OPENAI_ENDPOINT');
const AZURE_OPENAI_API_KEY = Deno.env.get('AZURE_OPENAI_API_KEY');

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  // 🔒 SECURITY: this endpoint uses a service_role client to read/write live
  // chat conversations. It must only be invoked by trusted internal callers
  // (other Edge Functions, CRON, server-side jobs) — not by browser visitors.
  const denied = requireInternalSecret(req, corsHeaders);
  if (denied) return denied;

  // V2d hardening — per-IP rate limit (defense-in-depth)
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
  const rl = checkRateLimit(`live-chat-ai-respond:$${ip}`, { limit: 15, windowSec: 60 });
  if (!rl.allowed) {
    return new Response(JSON.stringify({ error: 'Trop de requêtes, veuillez patienter.' }), {
      status: 429,
      headers: { ...corsHeaders, 'Content-Type': 'application/json', 'Retry-After': String(rl.retryAfterSec ?? 60) }
    });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const { conversation_id, message } = await req.json();

    if (!conversation_id || !message) {
      return new Response(
        JSON.stringify({ error: 'conversation_id et message sont requis' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 🔒 SECURITY: Sanitize user message before AI processing
    const sanitizedMessage = sanitizeForAI(message, {
      maxLength: 2000,
      strictMode: false,
      functionName: 'live-chat-ai-respond'
    });

    // Get conversation context
    const { data: conversation, error: convError } = await supabase
      .from('live_chat_conversations')
      .select('*, etablissement:etablissements(id, nom)')
      .eq('id', conversation_id)
      .single();

    if (convError) throw convError;

    // Get recent messages for context
    const { data: recentMessages, error: msgError } = await supabase
      .from('live_chat_messages')
      .select('*')
      .eq('conversation_id', conversation_id)
      .order('created_at', { ascending: false })
      .limit(10);

    if (msgError) throw msgError;

    // Search knowledge base for relevant articles
    const { data: articles, error: kbError } = await supabase
      .from('knowledge_base_articles')
      .select('id, title, content, category')
      .eq('status', 'published')
      .eq('visibility', 'public')
      .textSearch('title', message.split(' ').join(' | '), { type: 'websearch' })
      .limit(3);

    // If no results from title search, try content
    let relevantArticles = articles || [];
    if (relevantArticles.length === 0) {
      const { data: contentArticles } = await supabase
        .from('knowledge_base_articles')
        .select('id, title, content, category')
        .eq('status', 'published')
        .eq('visibility', 'public')
        .limit(5);
      relevantArticles = contentArticles || [];
    }

    // Build context from knowledge base
    const kbContext = relevantArticles.length > 0
      ? `Articles de la base de connaissances pertinents:\n$${relevantArticles.map(a => 
          `- $${a.title}: $${a.content?.substring(0, 500)}...`
        ).join('\n')}`
      : 'Aucun article pertinent trouvé dans la base de connaissances.';

    // Build conversation history
    const conversationHistory = (recentMessages || [])
      .reverse()
      .map(m => `$${m.sender_type === 'visitor' ? 'Client' : 'Support'}: $${m.content}`)
      .join('\n');

    // Prepare prompts
    const systemPrompt = `Tu es un assistant de support client intelligent pour Sclépios IA, une plateforme de gestion pour le secteur de la santé.

Tu dois:
1. Répondre de manière professionnelle et empathique
2. Utiliser les informations de la base de connaissances quand disponibles
3. Si tu ne peux pas répondre, suggérer d'escalader vers un agent humain
4. Garder tes réponses concises mais complètes (max 3-4 phrases)

$${kbContext}

Établissement client: $${conversation.etablissement?.nom || 'Non identifié'}`;

    // 🔒 SECURITY: Wrap user content with XML delimiters
    const wrappedMessage = wrapUserContent(sanitizedMessage, 'VISITOR_MESSAGE');

    const userPrompt = `Historique de la conversation:
$${conversationHistory}

Nouveau message du client: $${wrappedMessage}

Génère une réponse appropriée. Si tu proposes d'escalader, réponds avec le format JSON: {"escalate": true, "reason": "raison", "response": "message au client"}. Sinon réponds en texte simple.`;

    // Call Azure GPT-5
    if (!AZURE_OPENAI_ENDPOINT || !AZURE_OPENAI_API_KEY) {
      throw new Error('Azure OpenAI credentials not configured');
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 60000);

    let azureResponse: Response;
    try {
      azureResponse = await fetch(AZURE_OPENAI_ENDPOINT, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'api-key': AZURE_OPENAI_API_KEY,
        },
        body: JSON.stringify({
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          max_completion_tokens: 500,
          reasoning_effort: 'low',
          verbosity: 'low',
        }),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      if (azureResponse.status === 429) {
        await new Promise(r => setTimeout(r, 1000));
        azureResponse = await fetch(AZURE_OPENAI_ENDPOINT, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'api-key': AZURE_OPENAI_API_KEY,
          },
          body: JSON.stringify({
            messages: [
              { role: 'system', content: systemPrompt },
              { role: 'user', content: userPrompt }
            ],
            max_completion_tokens: 500,
            reasoning_effort: 'low',
            verbosity: 'low',
          }),
        });
      }
    } catch (error: unknown) {
      clearTimeout(timeoutId);
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error('Azure request timeout (60s)');
      }
      throw error;
    }

    if (!azureResponse.ok) {
      const errorText = await azureResponse.text();
      console.error('Azure API error:', azureResponse.status, errorText);
      throw new Error(`Azure API error: $${azureResponse.status}`);
    }

    const azureData = await azureResponse.json();
    const aiContent = azureData.choices?.[0]?.message?.content || '';

    // Parse response
    let shouldEscalate = false;
    let escalateReason = '';
    let responseText = aiContent;

    try {
      if (aiContent.includes('"escalate"')) {
        const jsonMatch = aiContent.match(/\{[\s\S]*"escalate"[\s\S]*\}/);
        if (jsonMatch) {
          const parsed = JSON.parse(jsonMatch[0]);
          shouldEscalate = parsed.escalate === true;
          escalateReason = parsed.reason || '';
          responseText = parsed.response || aiContent;
        }
      }
    } catch {
      // Keep aiContent as response if JSON parsing fails
    }

    // Save bot message
    const { error: insertError } = await supabase
      .from('live_chat_messages')
      .insert({
        conversation_id,
        content: responseText,
        content_type: 'text',
        sender_type: 'bot',
        sender_id: null,
        is_internal: false,
      });

    if (insertError) throw insertError;

    // Update conversation
    await supabase
      .from('live_chat_conversations')
      .update({ updated_at: new Date().toISOString() })
      .eq('id', conversation_id);

    // If escalation needed, update status
    if (shouldEscalate) {
      await supabase
        .from('live_chat_conversations')
        .update({
          status: 'escalated',
          escalated_at: new Date().toISOString(),
          escalated_reason: escalateReason || 'Demande client complexe',
        })
        .eq('id', conversation_id);
    }

    return new Response(
      JSON.stringify({
        success: true,
        response: responseText,
        escalated: shouldEscalate,
        escalate_reason: escalateReason,
        used_kb_articles: relevantArticles.map(a => a.id),
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error: unknown) {
    console.error('Error in live-chat-ai-respond:', error);
    return buildErrorResponse('live-chat-ai-respond', error, corsHeaders, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { z } from "zod";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const RequestSchema = z.object({
  account_id: z.string().uuid().optional(),
  dry_run: z.boolean().default(true),
});

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Auth check
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Unauthorized" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const body = await req.json().catch(() => ({}));
    const parsed = RequestSchema.safeParse(body);
    if (!parsed.success) {
      return new Response(
        JSON.stringify({ error: "Invalid request", details: parsed.error.flatten() }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const { account_id, dry_run } = parsed.data;
    const stalwartUrl = Deno.env.get("STALWART_URL") || "http://stalwart:8080";

    // Fetch accounts to migrate
    let query = supabase
      .from("user_email_accounts")
      .select("id, email_address, imap_host, imap_port, sync_method, is_active, sync_enabled")
      .eq("is_active", true)
      .eq("sync_enabled", true)
      .eq("sync_method", "imap");

    if (account_id) {
      query = query.eq("id", account_id);
    }

    const { data: accounts, error: accountsError } = await query;
    if (accountsError) {
      throw new Error(`Failed to fetch accounts: $${accountsError.message}`);
    }

    console.log(`🔄 Found $${accounts?.length || 0} IMAP accounts to evaluate for JMAP migration`);

    const results: Array<{
      account_id: string;
      email: string;
      status: string;
      jmap_reachable: boolean;
      message: string;
    }> = [];

    for (const account of accounts || []) {
      try {
        console.log(`📧 Evaluating $${account.email_address}...`);

        // Step 1: Check JMAP connectivity to Stalwart
        let jmapReachable = false;
        try {
          const resp = await fetch(`$${stalwartUrl}/.well-known/jmap`, {
            signal: AbortSignal.timeout(10000),
          });
          jmapReachable = resp.ok;
        } catch {
          jmapReachable = false;
        }

        if (!jmapReachable) {
          results.push({
            account_id: account.id,
            email: account.email_address,
            status: "skipped",
            jmap_reachable: false,
            message: "Stalwart JMAP endpoint unreachable",
          });
          continue;
        }

        // Step 2: Verify account exists in Stalwart
        // In a real implementation, we'd check via Stalwart admin API
        // For now, we verify JMAP session discovery works

        if (dry_run) {
          results.push({
            account_id: account.id,
            email: account.email_address,
            status: "ready",
            jmap_reachable: true,
            message: `Dry run: account eligible for JMAP migration (current: $${account.imap_host}:$${account.imap_port})`,
          });
          continue;
        }

        // Step 3: Switch sync_method to JMAP
        const { error: updateError } = await supabase
          .from("user_email_accounts")
          .update({ sync_method: "jmap" })
          .eq("id", account.id);

        if (updateError) {
          throw new Error(`Failed to update sync_method: $${updateError.message}`);
        }

        // Step 4: Trigger initial JMAP sync
        const { data: syncResult, error: syncError } = await supabase.functions.invoke(
          "sync-emails-jmap",
          { body: { account_id: account.id, historical_backfill: false } }
        );

        if (syncError) {
          // Rollback on failure
          await supabase
            .from("user_email_accounts")
            .update({ sync_method: "imap" })
            .eq("id", account.id);

          throw new Error(`JMAP sync test failed, rolled back: $${syncError.message}`);
        }

        results.push({
          account_id: account.id,
          email: account.email_address,
          status: "migrated",
          jmap_reachable: true,
          message: `Successfully migrated to JMAP. Initial sync: $${syncResult?.messages_synced || 0} messages`,
        });

        console.log(`✅ $${account.email_address} migrated to JMAP`);
      } catch (error: unknown) {
        const errorMsg = error instanceof Error ? error.message : "Unknown error";
        console.error(`❌ Migration failed for $${account.email_address}:`, errorMsg);
        results.push({
          account_id: account.id,
          email: account.email_address,
          status: "failed",
          jmap_reachable: false,
          message: errorMsg,
        });
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        dry_run,
        total_accounts: accounts?.length || 0,
        results,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("❌ Migration error:", error);
    return buildErrorResponse('migrate-to-jmap', error, corsHeaders, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { Resend } from "npm:resend@2.0.0";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";

const resend = new Resend(Deno.env.get("RESEND_API_KEY"));

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

// Simple rate limiting (in-memory)
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
const RATE_LIMIT_WINDOW = 60000; // 1 minute
const RATE_LIMIT_MAX_REQUESTS = 20;

function checkRateLimit(identifier: string): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(identifier);

  if (!record || now > record.resetAt) {
    rateLimitMap.set(identifier, { count: 1, resetAt: now + RATE_LIMIT_WINDOW });
    return true;
  }

  if (record.count >= RATE_LIMIT_MAX_REQUESTS) {
    return false;
  }

  record.count++;
  return true;
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    // SECURITY: Validate service role key
    const authHeader = req.headers.get("Authorization");
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    if (!authHeader || !authHeader.includes(serviceRoleKey)) {
      console.error("Unauthorized: Invalid service role key");
      return new Response(
        JSON.stringify({ error: "Unauthorized: Service role key required" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // SECURITY: Rate limiting
    const clientIp = req.headers.get("x-forwarded-for") || "unknown";
    if (!checkRateLimit(clientIp)) {
      console.warn(`Rate limit exceeded for IP: $${clientIp}`);
      return new Response(
        JSON.stringify({ error: "Rate limit exceeded" }),
        { status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      serviceRoleKey
    );

    // Get all users with pending AI suggestions
    const { data: suggestionsGrouped } = await supabase
      .from("ai_suggested_actions")
      .select(`
        etablissement_id,
        etablissements!inner(
          nom,
          commercial_id,
          chef_projet_id,
          csm_id
        )
      `)
      .eq("status", "pending");

    if (!suggestionsGrouped || suggestionsGrouped.length === 0) {
      console.log("No pending suggestions found");
      return new Response(JSON.stringify({ message: "No pending suggestions" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" }
      });
    }

    // Group suggestions by user
    const userSuggestions = new Map<string, { name: string; email: string; count: number; etablissements: Set<string> }>();

    for (const suggestion of suggestionsGrouped) {
      const userIds = [
        suggestion.etablissements.commercial_id,
        suggestion.etablissements.chef_projet_id,
        suggestion.etablissements.csm_id
      ].filter(Boolean);

      for (const userId of userIds) {
        if (!userSuggestions.has(userId)) {
          const { data: profile } = await supabase
            .from("profiles")
            .select("prenom, nom, email")
            .eq("id", userId)
            .single();

          if (profile) {
            userSuggestions.set(userId, {
              name: `$${profile.prenom} $${profile.nom}`,
              email: profile.email,
              count: 0,
              etablissements: new Set()
            });
          }
        }

        const userData = userSuggestions.get(userId);
        if (userData) {
          userData.count++;
          userData.etablissements.add(suggestion.etablissements.nom);
        }
      }
    }

    // Send emails
    let emailsSent = 0;
    for (const [userId, userData] of userSuggestions) {
      try {
        // Check user notification preferences
        const { data: profile } = await supabase
          .from("profiles")
          .select("preferences")
          .eq("id", userId)
          .single();

        const prefs = (profile?.preferences as any)?.notifications;
        const aiSuggestionsPrefs = prefs?.email_notifications?.ai_suggestions;

        // Skip if user has disabled AI suggestions notifications
        if (!aiSuggestionsPrefs?.enabled || aiSuggestionsPrefs?.frequency === 'never') {
          console.log(`Skipping notification for $${userData.email} - AI suggestions disabled`);
          continue;
        }

        const { getEmailSenderConfig } = await import("../_shared/email-sender-config.ts");
        const senderConfig = await getEmailSenderConfig();

        await resend.emails.send({
          from: senderConfig.notifications_from,
          to: [userData.email],
          subject: `$${userData.count} suggestion$${userData.count > 1 ? 's' : ''} IA en attente`,
          html: `
            <h2>Bonjour $${userData.name},</h2>
            <p>Vous avez <strong>$${userData.count} suggestion$${userData.count > 1 ? 's' : ''} IA</strong> en attente de validation.</p>
            <p>Établissements concernés :</p>
            <ul>
              $${Array.from(userData.etablissements).map(nom => `<li>$${nom}</li>`).join('')}
            </ul>
            <p>L'IA a détecté des actions potentielles basées sur les emails récents :</p>
            <ul>
              <li>Mises à jour de tâches</li>
              <li>Créations de nouvelles tâches</li>
              <li>Changements de statut</li>
              <li>Mises à jour de résumés</li>
            </ul>
            <p><a href="https://gestion-marque-ia.apercu.example.org/etablissements" style="background-color: #3B82F6; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; display: inline-block;">Traiter les suggestions</a></p>
            <p>Cordialement,<br>L'équipe Sclepios CRM</p>
          `,
        });

        emailsSent++;
        console.log(`Email sent to $${userData.email}`);
      } catch (emailError: unknown) {
        console.error(`Failed to send email to $${userData.email}:`, emailError);
      }
    }

    return new Response(JSON.stringify({
      success: true,
      emails_sent: emailsSent,
      total_suggestions: suggestionsGrouped.length
    }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" }
    });

  } catch (error) {
    console.error("Error in notify-pending-ai-suggestions:", error);
    return buildErrorResponse('notify-pending-ai-suggestions', error, corsHeaders, 500);
  }
});

/**
 * jarvis-daily-briefing - Génère un briefing quotidien personnalisé
 * 
 * JARVIS 7.0 - Phase 3.3
 * 
 * Fonctionnalités:
 * - Résumé des priorités du jour
 * - Alertes sur les risques (retards, trésorerie, etc.)
 * - Opportunités identifiées
 * - Événements importants
 * - Métriques clés
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";
import { validateServiceOrUser } from "../_shared/auth-helpers.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version',
};

interface BriefingSection {
  title: string;
  emoji: string;
  items: BriefingItem[];
  priority: 'high' | 'medium' | 'low';
}

interface BriefingItem {
  text: string;
  type: 'alert' | 'info' | 'opportunity' | 'task';
  entityType?: string;
  entityId?: string;
  actionUrl?: string;
}

interface DailyBriefing {
  greeting: string;
  date: string;
  sections: BriefingSection[];
  summary: {
    tasksToday: number;
    overdueItems: number;
    unreadEmails: number;
    upcomingMeetings: number;
  };
  generatedAt: string;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    // Auth: require authenticated user OR internal service call (CRON)
    const auth = await validateServiceOrUser(req);
    if (!auth.authorized) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    let requestBody: { user_id?: string } = {};
    try {
      requestBody = await req.json();
    } catch {
      // CRON mode: no body
    }

    // For non-service callers, force user_id to the authenticated user
    if (!auth.isServiceCall) {
      requestBody.user_id = auth.userId;
    }

    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // === CRON MODE: no user_id → process all users with push subscriptions ===
    if (!requestBody.user_id) {
      console.log('[Daily Briefing] CRON mode: processing all users with push subscriptions');

      const { data: subs } = await supabase
        .from('push_subscriptions')
        .select('user_id')
        .eq('is_active', true);

      const userIds = [...new Set((subs || []).map(s => s.user_id))];
      console.log(`[Daily Briefing] Found $${userIds.length} users`);

      let sent = 0;
      for (const uid of userIds) {
        try {
          // Call self with user_id to generate briefing
          const { data: briefingResult } = await supabase.functions.invoke('jarvis-daily-briefing', {
            body: { user_id: uid },
          });

          if (briefingResult?.success && briefingResult?.briefing) {
            const b = briefingResult.briefing;
            const summary = b.summary;
            const lines: string[] = [];
            if (summary.tasksToday > 0) lines.push(`📋 $${summary.tasksToday} tâche(s)`);
            if (summary.overdueItems > 0) lines.push(`⚠️ $${summary.overdueItems} en retard`);
            if (summary.unreadEmails > 0) lines.push(`📧 $${summary.unreadEmails} email(s) non lu(s)`);
            if (summary.upcomingMeetings > 0) lines.push(`📅 $${summary.upcomingMeetings} RDV`);

            if (lines.length > 0) {
              await supabase.functions.invoke('send-push-notification', {
                body: {
                  user_id: uid,
                  title: `☀️ $${b.greeting}`,
                  body: lines.join(' • '),
                  type: 'ai_suggestion',
                  url: '/',
                  tag: `daily-briefing-$${b.date}`,
                },
              });
              sent++;
            }
          }
        } catch (e) {
          console.error(`[Daily Briefing] Error for $${uid}:`, e);
        }
      }

      return new Response(JSON.stringify({ success: true, briefings_sent: sent, total: userIds.length }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // === SINGLE USER MODE ===
    const user_id = requestBody.user_id;
    console.log(`[Daily Briefing] Generating for user: $${user_id}`);

    // Récupérer le profil utilisateur
    const { data: profile } = await supabase
      .from('profiles')
      .select('prenom, nom, email')
      .eq('id', user_id)
      .single();

    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();
    const todayEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59).toISOString();
    const in7Days = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();
    const in30Days = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();

    // Exécuter toutes les requêtes en parallèle
    const [
      tasksTodayResult,
      overdueTasksResult,
      highPriorityTasksResult,
      unreadEmailsResult,
      urgentEmailsResult,
      upcomingMeetingsResult,
      overdueInvoicesResult,
      coldProspectsResult,
      openTicketsResult,
      expiringCertificatesResult,
      recentWinsResult,
    ] = await Promise.all([
      // Tâches pour aujourd'hui
      supabase
        .from('taches')
        .select('id, titre, priorite, echeance')
        .eq('responsable_id', user_id)
        .in('statut', ['A faire', 'En cours'])
        .gte('echeance', todayStart)
        .lte('echeance', todayEnd)
        .order('priorite', { ascending: false })
        .limit(10),

      // Tâches en retard
      supabase
        .from('taches')
        .select('id, titre, echeance, priorite, etablissement:etablissements(nom)')
        .eq('responsable_id', user_id)
        .in('statut', ['A faire', 'En cours'])
        .lt('echeance', todayStart)
        .order('echeance', { ascending: true })
        .limit(10),

      // Tâches haute priorité non terminées
      supabase
        .from('taches')
        .select('id, titre, echeance')
        .eq('responsable_id', user_id)
        .in('statut', ['A faire', 'En cours'])
        .eq('priorite', 'Haute')
        .order('echeance', { ascending: true, nullsFirst: false })
        .limit(5),

      // Emails non lus
      supabase
        .from('email_threads')
        .select('id, subject, ai_generated_title, category, unread_count')
        .gt('unread_count', 0)
        .eq('is_deleted', false)
        .eq('is_archived', false)
        .order('last_message_date', { ascending: false })
        .limit(20),

      // Emails urgents (catégorie support ou mots-clés)
      supabase
        .from('email_threads')
        .select('id, subject, ai_generated_title')
        .gt('unread_count', 0)
        .eq('is_deleted', false)
        .in('category', ['Support', 'Urgent', 'Commercial'])
        .limit(5),

      // Réunions aujourd'hui
      supabase
        .from('calendar_events')
        .select('id, title, start_time, end_time, location, etablissement:etablissements(nom)')
        .gte('start_time', todayStart)
        .lte('start_time', todayEnd)
        .order('start_time', { ascending: true })
        .limit(10),

      // Factures en retard (> 30 jours)
      supabase
        .from('factures')
        .select('id, numero, client_nom, montant_ttc, date_echeance')
        .eq('statut', 'Envoyée')
        .lt('date_echeance', todayStart)
        .order('date_echeance', { ascending: true })
        .limit(10),

      // Prospects froids (pas de contact > 14 jours)
      supabase
        .from('etablissements')
        .select('id, nom, ville, dernier_contact')
        .eq('statut', 'Prospect')
        .lt('dernier_contact', new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000).toISOString())
        .order('dernier_contact', { ascending: true })
        .limit(10),

      // Tickets support ouverts priorité haute
      supabase
        .from('support_tickets')
        .select('id, titre, priority, status, created_at')
        .in('status', ['open', 'in_progress'])
        .in('priority', ['high', 'critical'])
        .order('created_at', { ascending: true })
        .limit(5),

      // Certifications qui expirent bientôt
      supabase
        .from('rh_certifications')
        .select('id, nom, date_expiration, employe:profiles(prenom, nom)')
        .gt('date_expiration', todayStart)
        .lt('date_expiration', in30Days)
        .order('date_expiration', { ascending: true })
        .limit(5),

      // Victoires récentes (établissements convertis cette semaine)
      supabase
        .from('etablissements')
        .select('id, nom, statut, updated_at')
        .eq('statut', 'Client')
        .gte('updated_at', new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString())
        .order('updated_at', { ascending: false })
        .limit(3),
    ]);

    // Construire les sections du briefing
    const sections: BriefingSection[] = [];

    // Section PRIORITÉS DU JOUR
    const priorityItems: BriefingItem[] = [];

    // Tâches aujourd'hui
    (tasksTodayResult.data || []).forEach(task => {
      priorityItems.push({
        text: `$${task.priorite === 'Haute' ? '🔴' : task.priorite === 'Moyenne' ? '🟡' : '🟢'} $${task.titre}`,
        type: 'task',
        entityType: 'tache',
        entityId: task.id,
      });
    });

    // Réunions
    (upcomingMeetingsResult.data || []).forEach(event => {
      const time = new Date(event.start_time).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      const etabl = event.etablissement ? ` - $${(event.etablissement as any).nom}` : '';
      priorityItems.push({
        text: `📅 $${time} - $${event.title}$${etabl}`,
        type: 'info',
        entityType: 'calendar_event',
        entityId: event.id,
      });
    });

    if (priorityItems.length > 0) {
      sections.push({
        title: 'PRIORITÉS DU JOUR',
        emoji: '📊',
        items: priorityItems,
        priority: 'high',
      });
    }

    // Section ALERTES (retards, urgences)
    const alertItems: BriefingItem[] = [];

    // Tâches en retard
    (overdueTasksResult.data || []).forEach(task => {
      const daysLate = Math.ceil((now.getTime() - new Date(task.echeance!).getTime()) / (1000 * 60 * 60 * 24));
      const etabl = task.etablissement ? ` ($${(task.etablissement as any).nom})` : '';
      alertItems.push({
        text: `⚠️ "$${task.titre}"$${etabl} - $${daysLate} jour(s) de retard`,
        type: 'alert',
        entityType: 'tache',
        entityId: task.id,
      });
    });

    // Factures impayées
    (overdueInvoicesResult.data || []).forEach(facture => {
      const daysLate = Math.ceil((now.getTime() - new Date(facture.date_echeance!).getTime()) / (1000 * 60 * 60 * 24));
      alertItems.push({
        text: `💰 Facture $${facture.numero} - $${facture.client_nom} ($${facture.montant_ttc}€) - $${daysLate}j de retard`,
        type: 'alert',
        entityType: 'facture',
        entityId: facture.id,
      });
    });

    // Tickets critiques
    (openTicketsResult.data || []).forEach(ticket => {
      alertItems.push({
        text: `🎫 [$${ticket.priority?.toUpperCase()}] $${ticket.titre}`,
        type: 'alert',
        entityType: 'support_ticket',
        entityId: ticket.id,
      });
    });

    // Certificats expirants
    (expiringCertificatesResult.data || []).forEach(cert => {
      const daysUntil = Math.ceil((new Date(cert.date_expiration!).getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const employe = cert.employe ? `$${(cert.employe as any).prenom} $${(cert.employe as any).nom}` : 'Employé';
      alertItems.push({
        text: `📜 $${cert.nom} de $${employe} expire dans $${daysUntil} jours`,
        type: 'alert',
        entityType: 'certification',
        entityId: cert.id,
      });
    });

    if (alertItems.length > 0) {
      sections.push({
        title: 'ALERTES',
        emoji: '⚠️',
        items: alertItems.slice(0, 8), // Limiter à 8 alertes
        priority: 'high',
      });
    }

    // Section OPPORTUNITÉS
    const opportunityItems: BriefingItem[] = [];

    // Prospects froids à relancer
    (coldProspectsResult.data || []).forEach(prospect => {
      const daysSinceContact = prospect.dernier_contact 
        ? Math.ceil((now.getTime() - new Date(prospect.dernier_contact).getTime()) / (1000 * 60 * 60 * 24))
        : 'N/A';
      opportunityItems.push({
        text: `📞 $${prospect.nom} ($${prospect.ville || 'Ville inconnue'}) - Dernier contact: $${daysSinceContact} jours`,
        type: 'opportunity',
        entityType: 'etablissement',
        entityId: prospect.id,
      });
    });

    // Victoires récentes (motivation)
    (recentWinsResult.data || []).forEach(win => {
      opportunityItems.push({
        text: `🎉 Nouveau client: $${win.nom}`,
        type: 'info',
        entityType: 'etablissement',
        entityId: win.id,
      });
    });

    if (opportunityItems.length > 0) {
      sections.push({
        title: 'OPPORTUNITÉS',
        emoji: '💡',
        items: opportunityItems.slice(0, 6),
        priority: 'medium',
      });
    }

    // Section EMAILS
    const emailItems: BriefingItem[] = [];
    const urgentEmails = urgentEmailsResult.data || [];
    const allUnread = unreadEmailsResult.data || [];

    if (urgentEmails.length > 0) {
      urgentEmails.forEach(email => {
        emailItems.push({
          text: `📬 [URGENT] $${email.ai_generated_title || email.subject || 'Sans sujet'}`,
          type: 'alert',
          entityType: 'email_thread',
          entityId: email.id,
        });
      });
    }

    if (allUnread.length > urgentEmails.length) {
      emailItems.push({
        text: `📧 $${allUnread.length - urgentEmails.length} autres emails non lus`,
        type: 'info',
      });
    }

    if (emailItems.length > 0) {
      sections.push({
        title: 'EMAILS',
        emoji: '📧',
        items: emailItems,
        priority: 'medium',
      });
    }

    // Construire le greeting
    const hour = now.getHours();
    let timeGreeting = 'Bonjour';
    if (hour < 12) timeGreeting = 'Bonjour';
    else if (hour < 18) timeGreeting = 'Bon après-midi';
    else timeGreeting = 'Bonsoir';

    const userName = profile?.prenom || 'Utilisateur';

    const briefing: DailyBriefing = {
      greeting: `$${timeGreeting} $${userName} ! 👋`,
      date: now.toLocaleDateString('fr-FR', { 
        weekday: 'long', 
        day: 'numeric', 
        month: 'long', 
        year: 'numeric' 
      }),
      sections,
      summary: {
        tasksToday: (tasksTodayResult.data || []).length + (highPriorityTasksResult.data || []).length,
        overdueItems: (overdueTasksResult.data || []).length + (overdueInvoicesResult.data || []).length,
        unreadEmails: allUnread.length,
        upcomingMeetings: (upcomingMeetingsResult.data || []).length,
      },
      generatedAt: now.toISOString(),
    };

    // Optionnel: Stocker le briefing pour historique
    await supabase
      .from('jarvis_daily_briefings')
      .upsert({
        user_id,
        briefing_date: todayStart.split('T')[0],
        briefing_data: briefing,
        generated_at: now.toISOString(),
      }, {
        onConflict: 'user_id,briefing_date'
      });

    console.log(`[Daily Briefing] Generated $${sections.length} sections for $${userName}`);

    return new Response(
      JSON.stringify({ success: true, briefing }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    console.error('[Daily Briefing] Error:', error);
    return buildErrorResponse('jarvis-daily-briefing', error, corsHeaders, 500);
  }
});

/**
 * JARVIS 9.0 - Moteur d'Apprentissage Actif
 * 
 * Analyse les confirmations/rejets d'actions pour :
 * - Ajuster les seuils de confiance par type d'action
 * - Détecter les corrections utilisateur et en déduire des préférences
 * - Apprentissage actif par observation
 * - Auto-optimisation des réponses
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "@supabase/supabase-js";
import { buildErrorResponse } from "../_shared/error-sanitizer.ts";
import { validateServiceOrUser } from "../_shared/auth-helpers.ts";
import {
  detectUserCorrections,
  generateLearnedPreferences,
  calculateThresholdAdjustments,
  applyThresholdAdjustments,
  analyzeSentiment,
} from "./active-learning.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version',
};

interface LearningMetrics {
  action_type: string;
  total_executions: number;
  confirmations: number;
  rejections: number;
  confirmation_rate: number;
  avg_response_time_ms: number;
  user_satisfaction_score: number;
}

interface UserPreferences {
  communication_style: 'formal' | 'casual' | 'concise' | 'detailed';
  response_length: 'short' | 'medium' | 'long';
  preferred_actions: string[];
  avoided_actions: string[];
  peak_usage_hours: number[];
  favorite_templates: string[];
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    );

    const auth = await validateServiceOrUser(req);
    if (!auth.authorized) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }
    const body = await req.json();
    const { action, data } = body;
    const user_id = (!auth.isServiceCall && auth.userId) ? auth.userId : body.user_id;

    // Get profile
    const { data: profile } = await supabase
      .from('profiles')
      .select('id, full_name')
      .eq('user_id', user_id)
      .single();

    if (!profile) {
      return new Response(JSON.stringify({ error: 'Profile not found' }), {
        status: 404,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    switch (action) {
      case 'record_feedback': {
        // Enregistrer un feedback utilisateur
        const { action_type, accepted, execution_time_ms, feedback_score } = data;

        await supabase.from('jarvis_learning_data').upsert({
          user_id: profile.id,
          action_type,
          accepted,
          execution_time_ms,
          feedback_score,
          recorded_at: new Date().toISOString(),
        });

        return new Response(JSON.stringify({ success: true }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      case 'get_metrics': {
        // Récupérer les métriques d'apprentissage
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

        const { data: learningData } = await supabase
          .from('jarvis_learning_data')
          .select('*')
          .eq('user_id', profile.id)
          .gte('recorded_at', thirtyDaysAgo);

        // Grouper par type d'action
        const metricsByAction = new Map<string, LearningMetrics>();

        for (const entry of learningData || []) {
          const existing = metricsByAction.get(entry.action_type) || {
            action_type: entry.action_type,
            total_executions: 0,
            confirmations: 0,
            rejections: 0,
            confirmation_rate: 0,
            avg_response_time_ms: 0,
            user_satisfaction_score: 0,
          };

          existing.total_executions++;
          if (entry.accepted) existing.confirmations++;
          else existing.rejections++;
          existing.avg_response_time_ms = 
            (existing.avg_response_time_ms * (existing.total_executions - 1) + (entry.execution_time_ms || 0)) 
            / existing.total_executions;
          if (entry.feedback_score) {
            existing.user_satisfaction_score = 
              (existing.user_satisfaction_score * (existing.total_executions - 1) + entry.feedback_score) 
              / existing.total_executions;
          }

          metricsByAction.set(entry.action_type, existing);
        }

        // Calculer les taux de confirmation
        const metrics = Array.from(metricsByAction.values()).map(m => ({
          ...m,
          confirmation_rate: m.total_executions > 0 
            ? (m.confirmations / m.total_executions) * 100 
            : 0,
        }));

        return new Response(JSON.stringify({
          success: true,
          metrics,
          total_interactions: learningData?.length || 0,
        }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      case 'get_preferences': {
        // Récupérer les préférences apprises
        const { data: memoryData } = await supabase
          .from('jarvis_user_memory')
          .select('category, key, value')
          .eq('user_id', profile.id)
          .in('category', ['preference', 'instruction']);

        // Analyser l'historique pour déduire les préférences
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

        const { data: conversations } = await supabase
          .from('jarvis_conversations')
          .select('messages, created_at')
          .eq('user_id', user_id)
          .gte('created_at', thirtyDaysAgo)
          .limit(100);

        // Analyser les heures d'utilisation
        const hourCounts = new Array(24).fill(0);
        for (const conv of conversations || []) {
          const hour = new Date(conv.created_at).getHours();
          hourCounts[hour]++;
        }
        const avgUsage = hourCounts.reduce((a, b) => a + b, 0) / 24;
        const peakHours = hourCounts
          .map((count, hour) => ({ hour, count }))
          .filter(h => h.count > avgUsage * 1.5)
          .map(h => h.hour);

        // Construire les préférences
        const preferences: UserPreferences = {
          communication_style: detectCommunicationStyle(memoryData || []),
          response_length: detectResponseLength(memoryData || []),
          preferred_actions: [],
          avoided_actions: [],
          peak_usage_hours: peakHours,
          favorite_templates: [],
        };

        return new Response(JSON.stringify({
          success: true,
          preferences,
          memory_entries: memoryData?.length || 0,
        }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      case 'adjust_thresholds': {
        // Ajuster les seuils de confiance basé sur l'historique
        const { data: learningData } = await supabase
          .from('jarvis_learning_data')
          .select('action_type, accepted')
          .eq('user_id', profile.id)
          .order('recorded_at', { ascending: false })
          .limit(500);

        const actionStats = new Map<string, { accepted: number; rejected: number }>();

        for (const entry of learningData || []) {
          const stats = actionStats.get(entry.action_type) || { accepted: 0, rejected: 0 };
          if (entry.accepted) stats.accepted++;
          else stats.rejected++;
          actionStats.set(entry.action_type, stats);
        }

        // Calculer les nouveaux seuils recommandés
        const thresholdRecommendations: Record<string, number> = {};

        for (const [actionType, stats] of actionStats) {
          const total = stats.accepted + stats.rejected;
          if (total < 5) continue; // Pas assez de données

          const acceptRate = stats.accepted / total;

          // Si taux d'acceptation élevé, on peut être plus autonome
          // Si taux faible, on doit demander plus de confirmations
          if (acceptRate > 0.9) {
            thresholdRecommendations[actionType] = 0.5; // Seuil bas = plus autonome
          } else if (acceptRate > 0.7) {
            thresholdRecommendations[actionType] = 0.6;
          } else if (acceptRate > 0.5) {
            thresholdRecommendations[actionType] = 0.7;
          } else {
            thresholdRecommendations[actionType] = 0.9; // Seuil haut = toujours confirmer
          }
        }

        return new Response(JSON.stringify({
          success: true,
          threshold_recommendations: thresholdRecommendations,
          data_points: learningData?.length || 0,
        }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      case 'generate_report': {
        // Générer un rapport d'apprentissage mensuel
        const now = new Date();
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();

        const { data: monthData } = await supabase
          .from('jarvis_learning_data')
          .select('*')
          .eq('user_id', profile.id)
          .gte('recorded_at', startOfMonth);

        const { data: conversations } = await supabase
          .from('jarvis_conversations')
          .select('id, messages')
          .eq('user_id', user_id)
          .gte('created_at', startOfMonth);

        const report = {
          period: `$${now.toLocaleString('fr-FR', { month: 'long' })} $${now.getFullYear()}`,
          total_interactions: monthData?.length || 0,
          conversations_count: conversations?.length || 0,
          top_actions: getTopActions(monthData || []),
          acceptance_rate: calculateAcceptanceRate(monthData || []),
          avg_satisfaction: calculateAvgSatisfaction(monthData || []),
          recommendations: generateRecommendations(monthData || []),
          generated_at: now.toISOString(),
        };

        return new Response(JSON.stringify({
          success: true,
          report,
        }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      default:
        return new Response(JSON.stringify({ error: 'Invalid action' }), {
          status: 400,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
    }

  } catch (error) {
    console.error('[learning-engine] Error:', error);
    return buildErrorResponse('jarvis-learning-engine', error, corsHeaders, 500);
  }
});

function detectCommunicationStyle(memoryData: any[]): UserPreferences['communication_style'] {
  const stylePref = memoryData.find(m => m.key === 'communication_style');
  if (stylePref) return stylePref.value as UserPreferences['communication_style'];
  return 'casual'; // Default
}

function detectResponseLength(memoryData: any[]): UserPreferences['response_length'] {
  const lengthPref = memoryData.find(m => m.key === 'response_length');
  if (lengthPref) return lengthPref.value as UserPreferences['response_length'];
  return 'medium'; // Default
}

function getTopActions(data: any[]): { action: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const entry of data) {
    counts.set(entry.action_type, (counts.get(entry.action_type) || 0) + 1);
  }
  return Array.from(counts.entries())
    .map(([action, count]) => ({ action, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);
}

function calculateAcceptanceRate(data: any[]): number {
  if (data.length === 0) return 0;
  const accepted = data.filter(d => d.accepted).length;
  return Math.round((accepted / data.length) * 100);
}

function calculateAvgSatisfaction(data: any[]): number {
  const withScore = data.filter(d => d.feedback_score);
  if (withScore.length === 0) return 0;
  const sum = withScore.reduce((acc, d) => acc + d.feedback_score, 0);
  return Math.round((sum / withScore.length) * 10) / 10;
}

function generateRecommendations(data: any[]): string[] {
  const recommendations: string[] = [];

  const acceptanceRate = calculateAcceptanceRate(data);
  if (acceptanceRate < 50) {
    recommendations.push('Considérez réduire le mode autonome pour obtenir plus de confirmations');
  } else if (acceptanceRate > 90) {
    recommendations.push('Excellent taux d\'acceptation ! Vous pouvez augmenter l\'autonomie de Jarvis');
  }

  const avgSat = calculateAvgSatisfaction(data);
  if (avgSat < 3) {
    recommendations.push('Les réponses semblent nécessiter des ajustements. Vérifiez vos préférences');
  }

  const topActions = getTopActions(data);
  if (topActions.length > 0) {
    recommendations.push(`Action la plus utilisée: "$${topActions[0].action}" - créez un template pour gagner du temps`);
  }

  return recommendations;
}

